function toAirtableFields(patch) {
  const out = {};
  Object.keys(patch).forEach((k) => {
    if (!AIRTABLE_FIELD_MAP[k]) throw new Error('UNKNOWN_FIELD ' + k);
    if (patch[k] !== undefined) out[AIRTABLE_FIELD_MAP[k]] = patch[k];
  });
  return out;
}

